<?php
namespace App\Http\Controllers\Seeker;
use App\Http\Controllers\Controller; use App\Models\Offer; use App\Services\NotificationService; use Illuminate\Http\RedirectResponse;
class OfferController extends Controller { public function respond(Offer $offer, string $response): RedirectResponse { abort_unless(auth()->user()?->hasRole('job-seeker'),403); abort_unless(in_array($response,['accepted','rejected'],true),404); abort_unless($offer->application->candidate_id===auth()->id(),404); abort_unless($offer->status==='sent',422); $offer->update(['status'=>$response,'responded_at'=>now()]); $application=$offer->application; $application->update(['status'=>$response==='accepted'?'Offer Accepted':'Offer Rejected','last_activity_at'=>now()]); $companyUser=$offer->application->job->company->users()->first(); if($companyUser){app(NotificationService::class)->send($companyUser,'offer_response','Candidate responded to offer',"{$application->candidate->name} {$response} the {$offer->position} offer.",['offer_id'=>$offer->id],'offer_accepted');} return back()->with('success',"Offer {$response}."); } }